
#include "include/gbh38.h"

#include "hardware/pio.h"
#include "hardware/pio_instructions.h"
#include "gbh38.pio.h"  // Generated by pioasm

// PIO resources allocated during initialization
static PIO encoder_pio;
static unsigned int encoder_sm;
static unsigned int encoder_offset;

static bool encoder_initialized = false;
static uint32_t encoder_zero_offset = 0u;

// Address of "publish" in gbh38.pio
#define GBH38_PUBLISH_PC 15u

// Read the newest encoder measurement
static uint32_t encoder_get_raw_count(void) {
    uint32_t count = 0u;

    // Drain old measurements, then wait for a new one
    uint32_t samples =
        pio_sm_get_rx_fifo_level(encoder_pio, encoder_sm) + 1u;

    while (samples > 0u) {
        count = pio_sm_get_blocking(encoder_pio, encoder_sm);
        samples--;
    }

    return count;
}

// Get position relative to zero reference
int32_t encoder_get_position(void) {
    uint32_t raw_count = encoder_get_raw_count();
    return (int32_t)(raw_count - encoder_zero_offset);
}

// Set current position as zero
void encoder_reset_position(void) {
    encoder_zero_offset = encoder_get_raw_count();
}

// Convert counts to revolutions
float encoder_get_revolutions(void) {
    return (float)encoder_get_position() / ENCODER_COUNTS_PER_REV;
}

bool encoder_init(uint32_t pin_a, uint32_t pin_b) {
    // Validate consecutive GPIOs on Pico 2 headers
    bool valid_pair_start =
        (pin_a <= 21u || pin_a == 26u || pin_a == 27u);

    if (!valid_pair_start ||
        pin_b != pin_a + 1u ||
        encoder_initialized) {
        return false;
    }

    // Find a free PIO state machine and load the program
    if (!pio_claim_free_sm_and_add_program(
            &gbh38_program,
            &encoder_pio,
            &encoder_sm,
            &encoder_offset)) {
        return false;
    }

    // Connect GPIO A and B to the allocated PIO
    pio_gpio_init(encoder_pio, pin_a);
    pio_gpio_init(encoder_pio, pin_b);

    // Get configuration generated from gbh38.pio
    pio_sm_config config =
        gbh38_program_get_default_config(encoder_offset);

    // Configure input mapping
    sm_config_set_in_pins(&config, pin_a);

    // ISR shifts left; OSR shifts right
    sm_config_set_in_shift(&config, false, false, 32);
    sm_config_set_out_shift(&config, true, false, 32);

    // Keep TX and RX FIFOs separate
    sm_config_set_fifo_join(&config, PIO_FIFO_JOIN_NONE);

    // Run at system clock speed
    sm_config_set_clkdiv(&config, 1.0f);

    // Apply configuration; leave state machine disabled
    pio_sm_init(encoder_pio, encoder_sm, encoder_offset, &config);

    // Configure both GPIO pins as inputs
    pio_sm_set_consecutive_pindirs(
        encoder_pio, encoder_sm, pin_a, 2u, false
    );

    // Initialize X, the PIO position counter
    pio_sm_exec(encoder_pio, encoder_sm,
                pio_encode_set(pio_x, 0u));

    // Initialize previous A/B state from actual GPIO levels
    pio_sm_exec(encoder_pio, encoder_sm,
                pio_encode_mov(pio_isr, pio_null));

    pio_sm_exec(encoder_pio, encoder_sm,
                pio_encode_in(pio_pins, 2u));

    pio_sm_exec(encoder_pio, encoder_sm,
                pio_encode_mov(pio_osr, pio_isr));

    // Begin at "publish", not in the transition table
    pio_sm_exec(encoder_pio, encoder_sm,
                pio_encode_jmp(encoder_offset + GBH38_PUBLISH_PC));

    // Start state machine
    pio_sm_set_enabled(encoder_pio, encoder_sm, true);

    // Establish initial zero reference
    encoder_zero_offset = encoder_get_raw_count();

    encoder_initialized = true;
    return true;
}
